// 范围由 skill-ranges.ts 按原版 fw 矩阵逐阵位判定。

export type SkillBehavior = 'attack' | 'heal' | 'shield' | 'status' | 'revive' | 'advance-gauge' | 'grant-energy' | 'summon' | 'passive'
export interface CombatSkillContent {
  /** 原版 jn 表 id */
  id: number
  name: string
  /** 原版 jn[15] 行为字符串，供自动技能条件原样判断。 */
  originalBehavior: string
  behavior: SkillBehavior
  targetSide: 'enemy' | 'ally'
  route: 'external' | 'internal' | 'support'
  /** 元素 0 无 / 1 雷 / 2 水 / 3 火 / 4 木 / 5 土 / 6 精神 / 7 神圣 / 8 黑暗 */
  element: number
  /** 威力百分比（技能等级 1）；推条技能表示行动条推进百分比 */
  powerPercent: number
  /** 能量档 0-5；冷却 = 能量档 × 4 秒 */
  energyCost: number
  cooldownMs: number
  /** 原版 jn 字段 36“分段数”，只写入子弹表现实例，不增加碰撞伤害次数。 */
  hits: number
  /** 原版 jn[37] 范围类型；具体阵位矩阵见 skill-ranges.ts。 */
  rangeId: number
  reach: 'melee' | 'ranged'
  /** 技能系（专精乘区 60+cat-1） */
  skillCategory: number
  /** 原版 jn[49] 技能组；威力属性 id = 152 + skillGroupId，0 表示无技能组。 */
  skillGroupId: number
  /** 原版 jn[18]/jn[24]：技能结算后给施法者附加的 buff 与层数。 */
  selfBuffId?: number
  selfBuffStacks?: number
  appliedBuffId?: number
  appliedBuffChance?: number
  appliedBuffStacks?: number
  /** 增效：施法者身上每层该 buff 提升伤害百分比 */
  enhanceBuffId?: number
  enhancePerStack?: number
  enhanceTarget?: 'actor' | 'target'
  /** 原版 jn[43]：结算后消耗的增效 buff 层数；99 表示清空。 */
  enhanceConsumeStacks?: number
  /** 原版 jn[23]：复活后生命百分比。 */
  reviveHpPercent?: number
  summonId?: number
  passiveAttributes?: ReadonlyArray<{ sxId: number; value: number }>
}

